package cart

import "errors"

// Item is a priced line in a Cart.
type Item struct {
	SKU   string
	Cents int
	Qty   int
}

// ErrEmpty reports a cart with no items.
var ErrEmpty = errors.New("cart is empty")

// Cart holds items until checkout.
type Cart struct {
	items []Item
}

// Add puts an item in the cart.
func (c *Cart) Add(item Item) {
	c.items = append(c.items, item)
}

// Total returns the sum of every line in cents.
func (c *Cart) Total() (int, error) {
	if len(c.items) == 0 {
		return 0, ErrEmpty
	}
	total := 0
	for _, item := range c.items {
		total += item.Cents * item.Qty
	}
	return total, nil
}

