package cart

import "testing"

func cartWith(t *testing.T, items ...Item) *Cart {
	t.Helper()
	cart := &Cart{}
	for _, item := range items {
		cart.Add(item)
	}
	return cart
}

func line(sku string, cents, qty int) Item {
	return Item{SKU: sku, Cents: cents, Qty: qty}
}

func assertTotal(t *testing.T, cart *Cart, want int) {
	t.Helper()
	got, err := cart.Total()
	if err != nil {
		t.Fatalf("Total: %v", err)
	}
	if got != want {
		t.Fatalf("Total = %d, want %d", got, want)
	}
}

func TestTotalSumsLines(t *testing.T) {
	assertTotal(t, cartWith(t, line("pen", 150, 2), line("pad", 400, 1)), 700)
}

func TestTotalOfEmptyCartIsAnError(t *testing.T) {
	if _, err := cartWith(t).Total(); err != ErrEmpty {
		t.Fatalf("err = %v, want ErrEmpty", err)
	}
}
